new file mode 100644
index 0000000..0f3c3b4
--- /dev/null
+++ b/src/utils/redact.ts
@@ -0,0 +1,25 @@
+// Telegram bot tokens typically look like: 123456789:ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghi
+// They can appear either standalone or inside Bot API URLs:
+//   https://api.telegram.org/bot<TOKEN>/METHOD
+const BOT_TOKEN_RE = /\b\d{6,}:[A-Za-z0-9_-]{20,}\b/g;
+const BOT_TOKEN_IN_URL_RE =
+  /(https?:\/\/api\.telegram\.org\/bot)(\d{6,}:[A-Za-z0-9_-]{20,})(?=\/|$)/g;
+
+export function redactTelegramBotTokens(input: string): string {
+  // Keep the URL shape but remove the secret.
+  const redacted = input.replace(BOT_TOKEN_IN_URL_RE, "$1[redacted]");
+  // Also redact any remaining standalone tokens.
+  return redacted.replace(BOT_TOKEN_RE, "[redacted]");
+}

