index 0000000..2ce0c34
--- /dev/null
+++ b/packages/diracx-web-components/src/utils/sanitizeRedirect.ts
@@ -0,0 +1,29 @@
+/**
+ * Sanitizes a post-login redirect target to prevent open redirects.
+ *
+ * Only allow same-origin redirects expressed as absolute-path references
+ * (e.g. "/dashboard?x=1"). Reject scheme-relative ("//evil.com") and any
+ * non-path forms ("https://...", "javascript:...").
+ */
+export function sanitizeRedirect(redirect: string | null | undefined, fallback = "/"): string {
+  if (!redirect) {
+    return fallback;
+  }
+
+  const value = redirect.trim();
+  if (value === "") {
+    return fallback;
+  }
+
+  // Allow only absolute-path references and forbid scheme-relative URLs.
+  if (!value.startsWith("/") || value.startsWith("//")) {
+    return fallback;
+  }
+
+  // Backslashes can be interpreted inconsistently by user agents/proxies.
+  if (value.includes("\\") || value.includes("\u0000")) {
+    return fallback;
+  }
+
+  return value;
+}

