+// Comments are user-controlled input and must not allow raw HTML.
+// See CVE-2024-38527.
+const md = new MarkdownIt({
+  html: false,
+  linkify: true,
+  breaks: true,
+});
+
+// Tighten URL validation to prevent javascript:/data: style payloads via markdown links.
+// Allow http(s), mailto, and relative/fragment URLs.
+const SAFE_PROTOCOL_RE = /^(https?:|mailto:)/i;
+function isSafeLink(url: string): boolean {
+  const trimmed = (url || '').trim();
+  if (!trimmed) return false;
+
+  // Relative URLs / fragments are OK.
+  if (
+    trimmed.startsWith('#') ||
+    trimmed.startsWith('/') ||
+    trimmed.startsWith('./') ||
+    trimmed.startsWith('../') ||
+    trimmed.startsWith('?')
+  ) {
+    return true;
+  }
+
+  // If it has a scheme, it must be safe.
+  if (/^[a-zA-Z][a-zA-Z0-9+.-]*:/.test(trimmed)) {
+    return SAFE_PROTOCOL_RE.test(trimmed);
+  }
+
+  // No scheme -> treat as relative.
+  return true;
+}
+
+md.validateLink = isSafeLink;

 export function renderMarkdown(text: string): string {
   return md.render(text);
 }
