+/**
+ * Sanitizes URLs that can be attached to elements to prevent XSS via
+ * `javascript:`, `data:`, etc. We allow common safe protocols and also allow
+ * relative URLs (no explicit scheme).
+ *
+ * Returns `null` if the URL is considered unsafe.
+ */
+export const sanitizeUrl = (url: string): string | null => {
+  const trimmed = url.trim();
+  if (!trimmed) {
+    return null;
+  }
+
+  // Remove control chars from the actual value we keep.
+  const normalized = trimmed.replace(/[\u0000-\u001F\u007F-\u009F]/g, "");
+
+  // For scheme detection, additionally remove whitespace to prevent bypasses
+  // such as `java\nscript:` or `java\t script:`.
+  const schemeProbe = normalized.replace(
+    /[\s\u0000-\u001F\u007F-\u009F]+/g,
+    "",
+  );
+
+  const schemeMatch = schemeProbe.match(/^([a-zA-Z][a-zA-Z0-9+.-]*):/);
+  if (schemeMatch) {
+    const scheme = schemeMatch[1].toLowerCase();
+    if (!["http", "https", "mailto", "tel"].includes(scheme)) {
+      return null;
+    }
+  }
+
+  return normalized;
+};
+
