+function assertNoSensitiveFieldFiltering(collection: string, filter: unknown): void {
+	const sensitive = SENSITIVE_FILTER_FIELDS[collection];
+	if (!sensitive) return;
+
+	const walk = (node: unknown): void => {
+		if (Array.isArray(node)) {
+			for (const item of node) walk(item);
+			return;
+		}
+
+		if (!node || typeof node !== 'object') return;
+
+		for (const [key, value] of Object.entries(node as Record<string, unknown>)) {
+			// Logical / operator keys (e.g. _and, _or, _not) can contain nested filters
+			if (key.startsWith('_')) {
+				walk(value);
+				continue;
+			}
