+/**
+ * Sanitize a workspace path before embedding it into LLM prompts.
+ *
+ * Removes Unicode control/format characters (Cc/Cf), plus explicit line/paragraph
+ * separators (U+2028/U+2029), to prevent prompt-structure injection via
+ * crafted directory names.
+ */
+export function sanitizeWorkspacePath(input: string): string {
+  const s = String(input);
+  // \u2028 (LINE SEPARATOR) and \u2029 (PARAGRAPH SEPARATOR) are not in Cc/Cf.
+  return s.replace(/[\p{Cc}\p{Cf}\u2028\u2029]/gu, "");
+}
