--- /dev/null
+++ b/src/utils/argv.ts
@@ -0,0 +1,126 @@
+/**
+ * Minimal shell-style argv parsing used to validate rawCommand <-> argv consistency.
+ *
+ * Supports:
+ *  - whitespace separation
+ *  - single quotes: '...'
+ *  - double quotes: "..."
+ *  - backslash escaping outside quotes and inside double quotes
+ *
+ * This is NOT intended to be a full shell parser; it is only used to ensure that
+ * two representations of the same command cannot diverge for policy evaluation
+ * vs execution.
+ */
+export function parseRawCommandToArgv(rawCommand: string): string[] {
+  const s = String(rawCommand ?? "");
+  const argv: string[] = [];
+
+  let cur = "";
+  let started = false;
+  let quote: "'" | '"' | null = null;
+  let escape = false;
+
+  for (let i = 0; i < s.length; i++) {
+    const ch = s[i];
+
+    if (escape) {
+      cur += ch;
+      started = true;
+      escape = false;
+      continue;
+    }
+
+    if (quote === "'") {
+      if (ch === "'") {
+        quote = null;
+        started = true;
+      } else {
+        cur += ch;
+        started = true;
+      }
+      continue;
+    }
+
+    if (quote === '"') {
+      if (ch === '"') {
+        quote = null;
+        started = true;
+      } else if (ch === "\\") {
+        escape = true;
+      } else {
+        cur += ch;
+        started = true;
+      }
+      continue;
+    }
+
+    // not in quotes
+    if (ch === "'" || ch === '"') {
+      quote = ch as "'" | '"';
+      started = true;
+      continue;
+    }
+
+    if (ch === "\\") {
+      escape = true;
+      started = true;
+      continue;
+    }
+
+    if (/\s/.test(ch)) {
+      if (started) {
+        argv.push(cur);
+        cur = "";
+        started = false;
+      }
+      continue;
+    }
+
+    cur += ch;
+    started = true;
+  }
+
+  if (escape) {
+    // Trailing backslash: treat it as literal to avoid surprising drops.
+    cur += "\\";
+    started = true;
+  }
+
+  if (quote !== null) {
+    throw new Error("Invalid rawCommand: unterminated quote");
+  }
+
+  if (started) {
+    argv.push(cur);
+  }
+
+  return argv;
+}
+
+export function assertRawCommandMatchesArgv(rawCommand: string, command: string[]): void {
+  const parsed = parseRawCommandToArgv(rawCommand);
+  if (parsed.length !== command.length) {
+    throw new Error("rawCommand/command mismatch");
+  }
+  for (let i = 0; i < parsed.length; i++) {
+    if (parsed[i] !== command[i]) {
+      throw new Error("rawCommand/command mismatch");
+    }
+  }
+}
