@@ -0,0 +1,69 @@
+import fs from "node:fs/promises";
+import path from "node:path";
+import { Buffer } from "node:buffer";
+
+type LoadMediaOptions = {
+  /**
+   * Base directory for local media reads. Local paths are resolved within this root
+   * and must not escape it (including via symlinks).
+   */
+  localRoot?: string;
+};
+
+function isHttpUrl(input: string): boolean {
+  return /^https?:\/\//i.test(input);
+}
+
+function ensureNoNullBytes(input: string): void {
+  if (input.includes("\0")) {
+    throw new Error("Invalid path");
+  }
+}
+
+export async function loadMediaBuffer(mediaUrl: string, opts: LoadMediaOptions = {}): Promise<Buffer> {
+  if (!mediaUrl || typeof mediaUrl !== "string") {
+    throw new Error("mediaUrl is required");
+  }
+
+  if (isHttpUrl(mediaUrl)) {
+    const res = await fetch(mediaUrl);
+    if (!res.ok) throw new Error(`Failed to fetch mediaUrl: ${res.status}`);
+    return Buffer.from(await res.arrayBuffer());
+  }
+
+  // Local file path: restrict to a known root to prevent traversal/exfiltration.
+  ensureNoNullBytes(mediaUrl);
+
+  const localRoot = opts.localRoot ?? process.cwd();
+  const rootReal = await fs.realpath(localRoot);
+
+  // Resolve relative paths within the localRoot; absolute paths are allowed only if
+  // they still reside under localRoot after canonicalization.
+  const candidate = path.isAbsolute(mediaUrl) ? path.normalize(mediaUrl) : path.resolve(rootReal, mediaUrl);
+  const fileReal = await fs.realpath(candidate);
+
+  const rootWithSep = rootReal.endsWith(path.sep) ? rootReal : rootReal + path.sep;
+  if (!fileReal.startsWith(rootWithSep)) {
+    throw new Error("Refusing to read local file outside of localRoot");
+  }
+
+  return await fs.readFile(fileReal);
+}

