+import type { Response } from 'express';
+import { sendSuccessResponse } from './WebhookHelpers';
+
+function mockResponse() {
+	const headers: Record<string, unknown> = {};
+	const res = {
+		set: (h: Record<string, unknown>) => {
+			for (const [k, v] of Object.entries(h)) headers[k.toLowerCase()] = v;
+			return res;
+		},
+		setHeader: (k: string, v: unknown) => {
+			headers[k.toLowerCase()] = v;
+		},
+		getHeader: (k: string) => headers[k.toLowerCase()],
+		status: () => res,
+		send: () => res,
+		json: () => res,
+	} as unknown as Response;
+
+	return { res, headers };
+}
+
+describe('WebhookHelpers CSP sandbox', () => {
+	test('enforces CSP sandbox when workflow sets Content-Type: text/html', async () => {
+		const { res, headers } = mockResponse();
+
+		await sendSuccessResponse(
+			{} as any,
+			res,
+			'text',
+			'<script>alert(1)</script>',
+			200,
+			{ 'Content-Type': 'text/html; charset=utf-8' } as any,
+		);
+
+		expect(headers['content-security-policy']).toContain('sandbox');
+	});
+
+	test('does not overwrite existing CSP, but ensures sandbox directive is present', async () => {
+		const { res, headers } = mockResponse();
+
+		await sendSuccessResponse(
+			{} as any,
+			res,
+			'text',
+			'<b>ok</b>',
+			200,
+			{
+				'Content-Type': 'text/html',
+				'Content-Security-Policy': "default-src 'none'",
+			} as any,
+		);
+
+		expect(headers['content-security-policy']).toMatch(/sandbox/i);
+		expect(headers['content-security-policy']).toMatch(/default-src/i);
+	});
+});

